-- Data table: created when missing, never replaced or dropped (sim-engine/deploy). A run is registered
-- as RUNNING and filled, then ends DONE or FAILED; readers see DONE runs only. A killed RUNNING
-- run is later marked ABANDONED by the next lock holder; its input snapshot stays.
CREATE TABLE IF NOT EXISTS {SIM_SCHEMA}.SIM_RUN (
  RUN_ID           DECIMAL(18,0) IDENTITY NOT NULL COMMENT IS 'Run number, assigned on registration',
  RUN_STATUS       VARCHAR(10) UTF8 NOT NULL COMMENT IS 'RUNNING while the script works, DONE when every output is stored, FAILED after an error',
  RUN_ORIGIN       VARCHAR(8) UTF8 NOT NULL COMMENT IS 'MANUAL for a run started by hand, REFRESH for the weekly refresh step',
  RUN_LABEL        VARCHAR(200) UTF8 COMMENT IS 'Free label the caller gave the run, for example demo',
  LOAD_RUN_ID      DECIMAL(18,0) COMMENT IS 'The CFB_META.LOAD_RUN row of the refresh that started the run; NULL for a manual run',
  AS_OF_SEASON     DECIMAL(4,0) NOT NULL COMMENT IS 'Season of the as-of point the run simulated from',
  AS_OF_WEEK       DECIMAL(3,0) NOT NULL COMMENT IS 'Week number of the as-of point',
  AS_OF_SEASON_TYPE VARCHAR(10) UTF8 NOT NULL COMMENT IS 'regular or postseason, the season type of the as-of point',
  AS_OF_WEEK_SEQ   DECIMAL(3,0) NOT NULL COMMENT IS 'Sequence number of the as-of point within its season',
  AS_OF_LABEL      VARCHAR(100) UTF8 COMMENT IS 'Display label of the as-of point, for example 2026 after week 7',
  RUN_SEED         DECIMAL(18,0) NOT NULL COMMENT IS 'Seed of the run; with the batch layout and the input snapshot it reproduces every simulated season',
  N_SIMS           DECIMAL(18,0) NOT NULL COMMENT IS 'Number of simulated seasons',
  SIMS_PER_BATCH   DECIMAL(9,0) NOT NULL COMMENT IS 'Simulated seasons per engine call',
  N_BATCHES        DECIMAL(9,0) NOT NULL COMMENT IS 'Number of engine calls, N_SIMS divided by SIMS_PER_BATCH',
  N_TEAMS          DECIMAL(5,0) COMMENT IS 'Teams in the input snapshot; NULL until the snapshot is taken',
  N_GAMES          DECIMAL(5,0) COMMENT IS 'Remaining games simulated; NULL until the snapshot is taken',
  N_LEFT_OUT_GAMES DECIMAL(5,0) COMMENT IS 'Not-played games the run left out (after selection day or without both teams)',
  MODEL_DIGEST     VARCHAR(64) ASCII COMMENT IS 'SHA-256 of the parsed model rows, equal on the host and in the database',
  ENGINE_VERSION   VARCHAR(16) ASCII COMMENT IS 'First 16 hex digits of the SHA-256 of the engine script body',
  NUMPY_VERSION    VARCHAR(20) ASCII COMMENT IS 'numpy version inside the UDF that ran the batches',
  PYTHON_VERSION   VARCHAR(20) ASCII COMMENT IS 'Python version inside the UDF that ran the batches',
  INSTANCES        DECIMAL(5,0) COMMENT IS 'Distinct UDF instances that ran batches',
  NODES            DECIMAL(4,0) COMMENT IS 'Distinct database nodes that ran batches',
  STARTED_AT       TIMESTAMP NOT NULL COMMENT IS 'When the run was registered, UTC',
  ENDED_AT         TIMESTAMP COMMENT IS 'When the run ended, UTC; NULL while RUNNING',
  SECONDS_INPUTS   DECIMAL(9,3) COMMENT IS 'Seconds spent taking the input snapshot',
  SECONDS_ENGINE   DECIMAL(9,3) COMMENT IS 'Seconds spent in the engine statement',
  SECONDS_OUTPUTS  DECIMAL(9,3) COMMENT IS 'Seconds spent splitting the stage into the output tables',
  SECONDS_TOTAL    DECIMAL(9,3) COMMENT IS 'Seconds from registration to the end of the run',
  SIMS_PER_SECOND  DECIMAL(12,1) COMMENT IS 'Simulated seasons per second over the whole run',
  DETAIL           VARCHAR(2000) UTF8 COMMENT IS 'The error message of a FAILED run, else a one-line summary'
) COMMENT IS 'One row per simulation run: its as-of point, seed, size, versions, timings and status. Never dropped; runs stay for the season.';
